/* From Uiverse.io by MikeAndrewDesigner - Tags: animation, card, colorful, wave, cool card */
.__UIV_SCOPE__ .e-card {
  margin: 100px auto;
  background: transparent;
  box-shadow: 0px 8px 28px -9px rgba(0,0,0,0.45);
  position: relative;
  width: 240px;
  height: 330px;
  border-radius: 16px;
  overflow: hidden;
}

.__UIV_SCOPE__ .wave {
  position: absolute;
  width: 540px;
  height: 700px;
  opacity: 0.6;
  left: 0;
  top: 0;
  margin-left: -50%;
  margin-top: -70%;
  background: linear-gradient(744deg,#af40ff,#5b42f3 60%,#00ddeb);
}

.__UIV_SCOPE__ .icon {
  width: 3em;
  margin-top: -1em;
  padding-bottom: 1em;
}

.__UIV_SCOPE__ .infotop {
  text-align: center;
  font-size: 20px;
  position: absolute;
  top: 5.6em;
  left: 0;
  right: 0;
  color: rgb(255, 255, 255);
  font-weight: 600;
}

.__UIV_SCOPE__ .name {
  font-size: 14px;
  font-weight: 100;
  position: relative;
  top: 1em;
  text-transform: lowercase;
}

.__UIV_SCOPE__ .wave:nth-child(2),
.__UIV_SCOPE__ .wave:nth-child(3) {
  top: 210px;
}

.__UIV_SCOPE__ .playing .wave {
  border-radius: 40%;
  animation: wave 3000ms infinite linear;
}

.__UIV_SCOPE__ .wave {
  border-radius: 40%;
  animation: wave 55s infinite linear;
}

.__UIV_SCOPE__ .playing .wave:nth-child(2) {
  animation-duration: 4000ms;
}

.__UIV_SCOPE__ .wave:nth-child(2) {
  animation-duration: 50s;
}

.__UIV_SCOPE__ .playing .wave:nth-child(3) {
  animation-duration: 5000ms;
}

.__UIV_SCOPE__ .wave:nth-child(3) {
  animation-duration: 45s;
}

@keyframes wave {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}
